#[cfg(baseline)]
#[path = "baseline.rs"]
mod callback_quiescence;

#[cfg(optimized)]
#[path = "optimized.rs"]
mod callback_quiescence;

use callback_quiescence::LiveCallbackQuiescence;
use std::hint::black_box;
use std::sync::Arc;
use std::time::Instant;

#[inline(never)]
fn callback(quiescence: &Arc<LiveCallbackQuiescence>) {
    if let Some(guard) = black_box(quiescence).enter() {
        black_box(&guard);
    }
}

fn main() {
    let quiescence = Arc::new(LiveCallbackQuiescence::new());
    let started = Instant::now();

    for _ in 0..10_000_000 {
        callback(&quiescence);
    }

    println!("nanoseconds={}", started.elapsed().as_nanos());
    black_box(quiescence);
}

