#[test]
#[ignore = "local dispatch throughput measurement"]
fn measure_empty_preemption_dispatch() {
    use std::hint::black_box;
    use std::time::Instant;

    super::TEST_ICOUNT_RAW.set(0);
    let slot = NodeSlot::new(KIND_VM);
    let ceiling = authorize_advance_ceiling(0, 5000, None).unwrap();
    slot.publish_scheduler_advance(ceiling, crucible_shmem::AdvanceStopCondition::Ceiling)
        .unwrap();
    let state = super::test_live_state(1, 1, 0, &slot).unwrap();
    let started = Instant::now();

    for _ in 0..5_000_000 {
        black_box(black_box(&state).max_advance_icount()).unwrap();
    }

    println!("dispatches=5000000 nanoseconds={}", started.elapsed().as_nanos());
}
